<?php
declare(strict_types=1);
namespace StageArtCore\Presentation\PublicSite;
use StageArtCore\Domain\Member\MemberRepository;
final class MemberShortcodes{public function register():void{add_shortcode('stageart_members',[$this,'list']);add_shortcode('stageart_member',[$this,'detail']);}public function list():string{$members=(new MemberRepository())->all(true);ob_start();echo'<div class="stageart-members">';foreach($members as$m){$url=esc_url(home_url('/member/'.rawurlencode($m['slug']).'/'));echo'<article class="stageart-member"><a href="'.$url.'">'.($m['photo_id']?wp_get_attachment_image((int)$m['photo_id'],'medium'):'').'<h2>'.esc_html($m['name']).'</h2></a></article>';}echo'</div>';return(string)ob_get_clean();}public function detail():string{$slug=sanitize_title((string)($_GET['stageart_member']??''));if(!$slug)return'';$m=(new MemberRepository())->findBySlug($slug);if(!$m||$m['status']!=='published')return'';ob_start();echo'<article class="stageart-member-detail">';if($m['photo_id'])echo wp_get_attachment_image((int)$m['photo_id'],'large');echo'<h1>'.esc_html($m['name']).'</h1>';if($m['roles'])echo'<p>'.esc_html(implode('・',array_map(fn($r)=>MemberRepository::ROLES[$r]??$r,$m['roles']))).'</p>';if($m['profile'])echo'<div class="stageart-member-profile">'.wp_kses_post(wpautop($m['profile'])).'</div>';if($m['social']){echo'<ul class="stageart-member-social">';foreach($m['social']as$p=>$url)echo'<li><a rel="noopener" target="_blank" href="'.esc_url($url).'">'.esc_html(MemberRepository::SOCIAL_PLATFORMS[$p]??$p).'</a></li>';}echo'</ul></article>';return(string)ob_get_clean();}}
